<?php require '../includes/functions.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')die('Método no permitido');check_csrf();$id=(int)($_POST['id']??0);$st=$pdo->prepare('SELECT * FROM reports WHERE id=?');$st->execute([$id]);$r=$st->fetch();if(!$r)die('Reporte no encontrado');if((int)$r['user_id']!==(int)user()['id'] && user()['role']!=='admin'){http_response_code(403);die('Solo el autor puede modificar este reporte.');}$action=$_POST['action']??'';if($action==='resolve'){$pdo->prepare("UPDATE reports SET status='resolved' WHERE id=?")->execute([$id]);flash($r['type']==='lost'?'¡Caso resuelto! Marcaste que recuperaste el objeto que habías perdido.':'¡Caso resuelto! Marcaste que el objeto encontrado ya fue entregado a su dueño.');}elseif($action==='reopen'){$pdo->prepare("UPDATE reports SET status='open' WHERE id=?")->execute([$id]);flash('El reporte volvió a estar activo.');}elseif($action==='delete'){if($r['image']){@unlink(__DIR__.'/../uploads/'.$r['image']);}$pdo->prepare('DELETE FROM reports WHERE id=?')->execute([$id]);flash('Tu publicación fue eliminada.');header('Location: '.url('app.php'));exit;}header('Location: '.url('reports/view.php?id='.$id));exit;
